package inicio;

public class Ejercicio4 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		char probador;
		probador = 'c';
		System.out.println("probador: "+probador);
		probador++;
		System.out.println("probador: "+probador);
		System.out.println("probador: "+ ++probador + probador + 
				--probador + probador );
		
	}

}
